        "wall_seconds": time.monotonic() - started, "stdout": str(out), "stderr": str(err),
        "stdout_sha256": hashlib.sha256(out.read_bytes()).hexdigest(),
        "stderr_sha256": hashlib.sha256(err.read_bytes()).hexdigest(),
